inserted -> allocated { $g_remove(a, &m, ...) }
inserted -> safe { $free0(m) | $free(m) | $g_free(m) | $g_slice_free(?, m, ...) | $ldap_free(m, ...) | $vfree(...,m,?,32768) |
                    #ifblock(m, null, true) | #ifblock(f, null, false) | @Escape(m -> escapeArg) | #escape(m) |
                    $realloc(m, ?) | $winrealloc(m,...) | $xrealloc(m, ?) | $realloc_dbg(m, ...) | $renew(?, m, ...) | $try_realloc(m, ?) | $try_renew(?, m, ...) |
