            state nofree (start);
            state safe;
            state free : "pointer.freed";
            state inserted : "pointer.inserted";
            state used (error) : "pointer.usedafterfreed";
            var p;
            var a;
            pattern ignore_pattern {
		        $func_free0(p) |
                $func_free(p) |
	 	        $func_free1(p) |
		        $func_free2(p) |
		        p.$func_free4(...) |
		        p.$func_free5(...) |
		        $g_free(p) |
                $g_slice_free(?, p, ...) |
                $ldap_free(p, ...)
            }
	    pattern bad_pattern {
                *@p |
                #any_function(..., @p, ...) |
                #return(@p)
