            /* next three transitions are added for bug 9832 */
            nofree -> inserted { $g_append(a, &p, ...) | $g_insert(a, ?, &p, ...) }
            inserted -> nofree { $g_remove(a, &p, ...) }
            inserted -> free { $g_array_free(a, ?) }
            nofree -> free { $func_free0(p) | $func_free(p) | $func_free1(p) | $func_free2(p) |
                             p.$func_free4(...) | p.$func_free5(...) | $g_free(p) | $g_slice_free(?, p, ...) | $ldap_free(p, ...) }
            free -> safe { #any_function(..., &p, ...) }
            free -> free { pattern ignore_pattern }
            free -> used { pattern bad_pattern }

state start (start);
state maybeNull;
state notNull;
state deref(error);
var p;

start -> maybeNull { #ifblock(p, null, true) }
start -> maybeNull { p = null }
maybeNull -> notNull { #ifblock(p, null, false) }
maybeNull -> maybeNull { p = 0 }
maybeNull -> notNull { p = ? | #any_function(..., &p, ...) }
notNull -> maybeNull { p = null }
maybeNull -> deref { *p }

                state start Start;
                state       Decl : "stackvar.declared";
                state       Addr;
                state error Leak;

                var Var;
                var Addr;

		Start  -> Addr  { #buffer_declaration(Addr) }
                Start  -> Decl  { #any_declaration(Var) }
                Decl   -> Decl  { ? = Var } /* Follow addrs, not values */
                Decl   -> Decl  { Var = ? } /* Follow addrs, not values */
                Decl   -> Addr  { Addr = &Var }
                Decl   -> Leak  { #return(&Var) }
                Addr   -> Leak  { #return(Addr) }

