state start Start;
state Decl : "stackbuffer.declared";
state error Free;

var Var;

Start  -> Decl  { #buffer_declaration(Var) | #complex_declaration(Var) }
/* Decl   -> Free */
/* filled in with <ControlflowTransistion> */

state  start (start);
state  assignedNull:"statedesc.cpp.null_assigned";        // there's a path to here from null-asgn-to-tracked-p
state  surrogateAsgnNull;   // there's a path to here from null-asgn-to-tracked-p AND s == (p==null)
state  surrogateAsgnNot ;   // there's a path to here from null-asgn-to-tracked-p AND s == (p!=null)
state  dead;                // this bindingMap will be eliminated from the current StateSet
state  deref (error):"statedesc.cpp.null_deref";

var p;
var s;

start               -> assignedNull { p = null }

assignedNull        -> surrogateAsgnNull { s =  @p  == null }
assignedNull        -> surrogateAsgnNull { s = null ==  @p  }
assignedNull        -> surrogateAsgnNot  { s =  @p  != null }
assignedNull        -> surrogateAsgnNot  { s = null !=  @p  }

assignedNull        -> deref { @p.#any_function(...) | *@p }
surrogateAsgnNull   -> deref { @p.#any_function(...) | *@p }
surrogateAsgnNot    -> deref { @p.#any_function(...) | *@p }

assignedNull        -> dead { #ifblock( @p == null, false) }
surrogateAsgnNull   -> dead { #ifblock( @s,         false) }
surrogateAsgnNot    -> dead { #ifblock( @s,          true) }

assignedNull        -> dead { @p = ? }
surrogateAsgnNull   -> dead { @p = ? }
surrogateAsgnNot    -> dead { @p = ? }
surrogateAsgnNull   -> assignedNull { @s = ? }
surrogateAsgnNot    -> assignedNull { @s = ? }

state start (start);
state testedNull:"statedesc.cpp.maybe_null";        // implies tracked p is null
state surrogateTestNull; // implies tracked p  AND s == (p == null)
state surrogateTestNot ; // implies tracked p  AND s == (p == null)
state dead;              // implies this bindingMap discarded from the StateSet
state deref (error):"statedesc.cpp.null_deref";

var p;
var s;

start               -> testedNull { #ifblock(p == null,   true) }

start               -> surrogateTestNull { s = p == null }
start               -> surrogateTestNull { s = null == p }
start               -> surrogateTestNot  { s = p != null }
start               -> surrogateTestNot  { s = null != p }

testedNull          -> testedNull { s = @p == null | s = null == @p | s = @p != null | s = null != @p }

surrogateTestNull   -> testedNull { #ifblock(@p == null,  true) }
surrogateTestNot    -> testedNull { #ifblock(@p == null, false) }

surrogateTestNull   -> testedNull { #ifblock(@s,  true) }
surrogateTestNot    -> testedNull { #ifblock(@s, false) }

testedNull          -> deref { @p.#any_function(...) | *@p }
testedNull          -> dead { #ifblock( @p == null,  true) }
testedNull          -> dead { #ifblock( @p == null, false) }
testedNull          -> dead { #ifblock( @s,  true) }
testedNull          -> dead { #ifblock( @s, false) }

testedNull          -> dead { @p = ?          }
surrogateTestNull   -> dead { @p = ? | @s = ? }
surrogateTestNot    -> dead { @p = ? | @s = ? }

