    //BufferWrite(dest, 0, min(n, src.$strlen*int.$MAX_MB_LEN + 1))
    // MAX_MB_LEN not available, assume 4
    Ensures(dest.$strlen' <= min(src.$strlen*4, n - 1))
    //Ensures(dest.$strlen' <= min(src.$strlen*int.$MAX_MB_LEN, n - 1))
    Ensures(dest.$strlen' >= min(src.$strlen, (n - 1)/4))
    //Ensures(dest.$strlen' >= min(src.$strlen, (n - 1)/int.$MAX_MB_LEN))
    Ensures(dest.$size' == dest.$size)
    Ensures(dest.$offset' == dest.$offset)
    Ensures(return <= min(n-1, src.$strlen*4))
    //Ensures(return <= min(n-1, src.$strlen*int.$MAX_MB_LEN))
    Ensures(return >= 0 - 1)
}

