                    //BufferRead(src, 0, min(src.$strlen, nbytes))
                    //BufferWrite(dest, dest.$strlen*int.$MB_MAX_LEN, min((src.$strlen + 1)*int.$MB_MAX_LEN, nbytes))
                    BufferWrite(dest, dest.$strlen*4, min((src.$strlen + 1)*4, nbytes))
                    // use 4 for int.$MB_MAX_LEN
                    Ensures(dest.$strlen' <= dest.$strlen + min(src.$strlen, nbytes - 1))
                    //Ensures(dest.$strlen'*int.$MB_MAX_LEN >= dest.$strlen*int.$MB_MAX_LEN + min(src.$strlen*int.$MB_MAX_LEN, nbytes - 1))
                    Ensures(dest.$strlen'*4 >= dest.$strlen*4 + min(src.$strlen*4, nbytes - 1))
                    Ensures(dest.$offset' = dest.$offset)
                    Ensures(dest.$size' == dest.$size)
                    Ensures(return.$strlen <= dest.$strlen + min(src.$strlen, nbytes - 1))
                    //Ensures(return.$strlen*int.$MB_MAX_LEN >= dest.$strlen*int.$MB_MAX_LEN + min(src.$strlen*int.$MB_MAX_LEN, nbytes - 1))
                    Ensures(return.$offset == dest.$offset)
                    Ensures(return.$size == dest.$size)

		    controlflow:
			Copy(in=dest, out=return)
                }

                _mbsnbcat_l (dest,src,nbytes,locale) {
                    //BufferRead(src, 0, min(src.$strlen, nbytes))
                    //BufferWrite(dest, dest.$strlen*int.$MB_MAX_LEN, min((src.$strlen + 1)*int.$MB_MAX_LEN, nbytes))
                    BufferWrite(dest, dest.$strlen*4, min((src.$strlen + 1)*4, nbytes))
                    // use 4 for int.$MB_MAX_LEN
                    Ensures(dest.$strlen' <= dest.$strlen + min(src.$strlen, nbytes - 1))
                    //Ensures(dest.$strlen'*int.$MB_MAX_LEN >= dest.$strlen*int.$MB_MAX_LEN + min(src.$strlen*int.$MB_MAX_LEN, nbytes - 1))
                    Ensures(dest.$strlen'*4 >= dest.$strlen*4 + min(src.$strlen*4, nbytes - 1))
                    Ensures(dest.$offset' = dest.$offset)
