_mbsdup(s) {
    //BufferRead(s, 0, s.$strlen*int.$MB_MAX_LEN)
    BufferRead(s, 0, s.$strlen*4)
    Ensures(return.$strlen == s.$strlen)
    Ensures(return.$size >= s.$strlen + 1)
